func TrimQuotes(str string) string {
	// Regex match the string starts with qoute("),
	// this is so that strings like this(visibility = ["//tools/build_langserver/...", "//src/core"]) won't be matched
	re := regexp.MustCompile(`(^("|')([^"]|"")*("|'))`)

