func newSubscription(t *topic, ackDeadline time.Duration) *subscription {
	s := &subscription{
		topic:       t,
		ackDeadline: ackDeadline,
		msgs:        map[driver.AckID]*message{},
	}
	if t != nil {
		t.mu.Lock()
		defer t.mu.Unlock()
		t.subs = append(t.subs, s)
	}
	return s
}

